runner.runProbe:
const { setTimeout: delay } = await import('node:timers/promises');
const seen = [];
const service = submission.createTaskService(async value => { seen.push(value); await delay(15); return value * 2; }, { maxQueued: 1 });
try {
  const first = service.submit(3);
  const second = service.submit(4);
  const third = service.submit(5).catch(error => error.code);
  const during = service.stats();
  const results = await Promise.all([first, second, third]);
  await service.close();
  observe({ during, results, seen, final: service.stats() });
} finally { await service.close(); }

